using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using LocalRaidShared;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class ItemLootWeights {
 static bool loaded,enabled,onlyConfigured;static string search="",lastSearch="\0",selected="",draft="1",notice="";static readonly Dictionary<string,double> rules=new();static (string Id,string Name)[] entries=Array.Empty<(string,string)>();static Vector2 scroll;
 static void Load(){var value=NextRaidLoot.Read();enabled=value.ItemWeightsEnabled;rules.Clear();foreach(var pair in value.ItemWeights)rules[pair.Key]=pair.Value;loaded=true;lastSearch="\0";}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;FeatureToasts.Show(notice);}}
 static void Toggle(){var value=NextRaidLoot.Read();value.ItemWeightsEnabled=!enabled;NextRaidLoot.Save(value);enabled=value.ItemWeightsEnabled;FeatureToasts.Show("单物品生成权重",enabled);}
 static void Save(){if(selected.Length==0)throw new ArgumentException("先从列表选择物品。");if(!double.TryParse(draft,NumberStyles.Float,CultureInfo.InvariantCulture,out var factor)||!double.IsFinite(factor)||factor<0)throw new ArgumentException("权重须为非负有限数字。");var value=NextRaidLoot.Read();value.ItemWeights[selected]=factor;value.ItemWeightsEnabled=true;NextRaidLoot.Save(value);Load();notice="已保存："+ItemSpawner.TemplateName(selected)+" ×"+factor.ToString("G6",CultureInfo.InvariantCulture)+"，随后生成生效。";FeatureToasts.Show("单物品权重已保存");}
 static void Remove(){var value=NextRaidLoot.Read();value.ItemWeights.Remove(selected);NextRaidLoot.Save(value);Load();draft="1";notice="已移除这件物品的独立规则。";FeatureToasts.Show(notice);}
 internal static void Draw(Rect rect){if(!loaded)Action(Load);float x=rect.x,y=rect.y,w=rect.width;if(InterfaceMenu.Button(new Rect(x,y,Math.Min(330,w*.55f),34),enabled?"独立物品权重 · 开启":"独立物品权重 · 关闭",enabled))Action(Toggle);if(InterfaceMenu.Button(new Rect(x+w-126,y,126,34),"重新读取"))Action(Load);y+=46;InterfaceMenu.Paragraph(new Rect(x,y,w,50),"0 不参与随机生成 · 1 原始权重 · 数值越大越容易抽中。独立规则优先于高价值倍率，适用于散落物、容器和空投，任务必刷物保留。",null,12);y+=62;search=InterfaceMenu.Field(new Rect(x,y,w-184,32),search);if(InterfaceMenu.Button(new Rect(x+w-174,y,174,32),onlyConfigured?"只看已设置（"+rules.Count+"）":"显示全部物品")){onlyConfigured=!onlyConfigured;lastSearch="\0";}y+=44;if(search!=lastSearch){Action(()=>{entries=ItemSpawner.FindTemplates(search).Where(item=>!onlyConfigured||rules.ContainsKey(item.Id)).ToArray();lastSearch=search;scroll=Vector2.zero;});}float left=w*.55f,gap=18,right=w-left-gap;var view=new Rect(x,y,left,Math.Max(100,rect.yMax-y-112));scroll=GUI.BeginScrollView(view,scroll,new Rect(0,0,left-20,Math.Max(view.height-1,entries.Length*58)));int first=Math.Max(0,(int)(scroll.y/58)),end=Math.Min(entries.Length,first+(int)Math.Ceiling(view.height/58)+2);for(int i=first;i<end;i++){var item=entries[i];string weight=rules.TryGetValue(item.Id,out var value)?" · ×"+value.ToString("G5",CultureInfo.InvariantCulture):"";if(InterfaceMenu.Button(new Rect(0,i*58,left-26,52),item.Name+weight,selected==item.Id)){selected=item.Id;draft=rules.GetValueOrDefault(selected,1).ToString("G17",CultureInfo.InvariantCulture);}}GUI.EndScrollView();float rx=x+left+gap;InterfaceMenu.Paragraph(new Rect(rx,y,right,64),selected.Length>0?ItemSpawner.TemplateName(selected):"搜索并选择要调整的物品",InterfaceMenu.Accent,15);InterfaceMenu.Label(new Rect(rx,y+76,right,28),"独立权重倍率",null,13);draft=InterfaceMenu.Field(new Rect(rx,y+112,right,34),draft);bool old=GUI.enabled;GUI.enabled=old&&selected.Length>0;if(InterfaceMenu.Button(new Rect(rx,y+162,right,36),"保存这件物品的权重"))Action(Save);GUI.enabled=old&&rules.ContainsKey(selected);if(InterfaceMenu.Button(new Rect(rx,y+212,right,34),"恢复这件物品默认"))Action(Remove);GUI.enabled=old;InterfaceMenu.Paragraph(new Rect(rx,y+264,right,85),"只能调整原有候选池中的物品；不会强行新增地图没有的物资。整枪按枪本体调整，不改变配件。",null,12);float bottom=rect.yMax-100;if(InterfaceMenu.Button(new Rect(x,bottom,210,32),"清空单物品规则"))Action(()=>{var value=NextRaidLoot.Read();value.ItemWeights.Clear();value.ItemWeightsEnabled=false;NextRaidLoot.Save(value);Load();notice="单物品规则已清空，其他物资设置保留。";FeatureToasts.Show(notice);});InterfaceMenu.Paragraph(new Rect(x,bottom+42,w,58),notice+"\n"+NextRaidLoot.ServerStatus,InterfaceMenu.Accent,12);}
}
